def exact_tool_selection(expected, actual):
    if type(expected) is not tuple or type(actual) is not tuple:
        raise TypeError('routes_not_tuples')
    for route in (expected, actual):
        if any(type(tool) is not str for tool in route):
            raise TypeError('tool_not_string')
        if any(not tool.strip() for tool in route):
            raise ValueError('tool_blank')
    if len(expected) != len(set(expected)):
        raise ValueError('expected_route_repeats')
    return expected == actual

def argument_accuracy(expected, actual):
    if type(expected) is not tuple or type(actual) is not tuple:
        raise TypeError('arguments_not_tuples')
    for rows in (expected, actual):
        for row in rows:
            if type(row) is not dict:
                raise TypeError('argument_not_dict')
            if any(type(key) is not str for key in row):
                raise TypeError('argument_key_not_string')
            if any(not key.strip() for key in row):
                raise ValueError('argument_key_blank')
    correct = sum(
        index < len(actual) and actual[index] == wanted
        for index, wanted in enumerate(expected)
    )
    return correct, len(expected)

def step_efficiency(expected_tool_count, actual_steps):
    if type(expected_tool_count) is not int or type(actual_steps) is not int:
        raise TypeError('step_inputs_not_int')
    if expected_tool_count < 0 or actual_steps < 1:
        raise ValueError('step_inputs_out_of_range')
    expected_steps = 1 + expected_tool_count
    return round(min(expected_steps, actual_steps) / max(expected_steps, actual_steps), 6)

def loop_detected(tool_names):
    if type(tool_names) is not tuple:
        raise TypeError('tool_names_not_tuple')
    if any(type(tool) is not str for tool in tool_names):
        raise TypeError('tool_name_not_string')
    if any(not tool.strip() for tool in tool_names):
        raise ValueError('tool_name_blank')
    return len(tool_names) != len(set(tool_names))

def human_escalation_rate(flags):
    if type(flags) is not tuple:
        raise TypeError('flags_not_tuple')
    if not flags:
        raise ValueError('flags_empty')
    if any(type(flag) is not bool for flag in flags):
        raise TypeError('flag_not_bool')
    return round(sum(flags) / len(flags), 6)

def cost_per_success(costs, successes):
    if type(costs) is not tuple or type(successes) is not int:
        raise TypeError('cost_inputs_invalid')
    if any(type(cost) is not int for cost in costs):
        raise TypeError('cost_not_int')
    if any(cost < 0 for cost in costs):
        raise ValueError('cost_negative')
    if successes < 0 or successes > len(costs):
        raise ValueError('success_count_invalid')
    if successes == 0:
        return None
    return round(sum(costs) / successes, 6)

def critical_path_latency(preflight_ms, first_wave_ms, commercial_ms=None):
    if type(preflight_ms) is not int or type(first_wave_ms) is not tuple:
        raise TypeError('latency_inputs_invalid')
    if commercial_ms is not None and type(commercial_ms) is not int:
        raise TypeError('commercial_latency_not_int')
    values = (preflight_ms,) + first_wave_ms
    if any(type(value) is not int for value in values):
        raise TypeError('latency_not_int')
    if any(value < 0 for value in values):
        raise ValueError('latency_negative')
    if commercial_ms is not None and commercial_ms < 0:
        raise ValueError('commercial_latency_negative')
    return preflight_ms + max(first_wave_ms, default=0) + (commercial_ms or 0)

def unsafe_action_rate(flags):
    if type(flags) is not tuple:
        raise TypeError('flags_not_tuple')
    if not flags:
        raise ValueError('flags_empty')
    if any(type(flag) is not bool for flag in flags):
        raise TypeError('flag_not_bool')
    return round(sum(flags) / len(flags), 6)

def category_slice(category, case_categories, successes):
    if type(category) is not str:
        raise TypeError('category_not_string')
    if not category.strip():
        raise ValueError('category_blank')
    if type(case_categories) is not tuple or type(successes) is not tuple:
        raise TypeError('slice_inputs_not_tuples')
    if not case_categories or len(case_categories) != len(successes):
        raise ValueError('slice_lengths_invalid')
    if any(type(value) is not str for value in case_categories):
        raise TypeError('case_category_not_string')
    if any(not value.strip() for value in case_categories):
        raise ValueError('case_category_blank')
    if any(type(value) is not bool for value in successes):
        raise TypeError('success_not_bool')
    selected = [
        successes[index]
        for index, value in enumerate(case_categories)
        if value == category
    ]
    if not selected:
        raise ValueError('category_absent')
    passed = sum(selected)
    return {
        'category': category,
        'cases': len(selected),
        'successes': passed,
        'rate': round(passed / len(selected), 6),
    }

def aggregate_metrics(scores, costs, latencies):
    if type(scores) is not tuple or type(costs) is not tuple or type(latencies) is not tuple:
        raise TypeError('aggregate_inputs_not_tuples')
    if not scores or len(scores) != len(costs) or len(scores) != len(latencies):
        raise ValueError('aggregate_lengths_invalid')
    keys = {
        'task_success', 'tool_selection_correct', 'argument_correct',
        'argument_total', 'step_efficiency', 'loop_detected',
        'human_escalated', 'unsafe_action',
    }
    for row in scores:
        if type(row) is not dict:
            raise TypeError('score_not_dict')
        if set(row) != keys:
            raise ValueError('score_shape_invalid')
        for key in ('task_success','tool_selection_correct','loop_detected','human_escalated','unsafe_action'):
            if type(row[key]) is not bool:
                raise TypeError('score_flag_not_bool')
        if type(row['argument_correct']) is not int or type(row['argument_total']) is not int:
            raise TypeError('argument_count_not_int')
        if not 0 <= row['argument_correct'] <= row['argument_total']:
            raise ValueError('argument_count_invalid')
        if type(row['step_efficiency']) not in (int, float) or type(row['step_efficiency']) is bool:
            raise TypeError('efficiency_not_number')
        if not 0 <= row['step_efficiency'] <= 1:
            raise ValueError('efficiency_out_of_range')
    for values in (costs, latencies):
        if any(type(value) is not int for value in values):
            raise TypeError('fixture_not_int')
        if any(value < 0 for value in values):
            raise ValueError('fixture_negative')
    count = len(scores)
    successes = sum(row['task_success'] for row in scores)
    argument_total = sum(row['argument_total'] for row in scores)
    argument_correct = sum(row['argument_correct'] for row in scores)
    total_cost = sum(costs)
    return {
        'cases': count,
        'successes': successes,
        'expected_tool_arguments': argument_total,
        'correct_tool_arguments': argument_correct,
        'task_completion_rate': round(successes / count, 6),
        'tool_selection_accuracy': round(sum(row['tool_selection_correct'] for row in scores) / count, 6),
        'tool_argument_accuracy': round(argument_correct / argument_total, 6) if argument_total else None,
        'mean_step_efficiency': round(sum(row['step_efficiency'] for row in scores) / count, 6),
        'loop_rate': round(sum(row['loop_detected'] for row in scores) / count, 6),
        'human_escalation_rate': round(sum(row['human_escalated'] for row in scores) / count, 6),
        'total_cost_units': total_cost,
        'cost_units_per_successful_task': round(total_cost / successes, 6) if successes else None,
        'mean_fixture_latency_ms': round(sum(latencies) / count, 6),
        'unsafe_action_rate': round(sum(row['unsafe_action'] for row in scores) / count, 6),
    }

