import hashlib

def dataset_digest(raw):
    if type(raw) is not bytes:
        raise TypeError('dataset_not_bytes')
    if not raw:
        raise ValueError('dataset_empty')
    if len(raw) > 1_000_000:
        raise ValueError('dataset_too_large')
    return hashlib.sha256(raw).hexdigest()

def validate_manifest(manifest, cases):
    if type(manifest) is not dict or type(cases) is not tuple:
        raise TypeError('manifest_inputs_invalid')
    if set(manifest) != {'dataset_id','version','case_count'}:
        raise ValueError('manifest_shape_invalid')
    if type(manifest['dataset_id']) is not str or type(manifest['version']) is not str or type(manifest['case_count']) is not int:
        raise TypeError('manifest_field_type_invalid')
    if manifest['dataset_id'] != 'week18-procurement-agent-v1' or manifest['case_count'] != 28:
        raise ValueError('manifest_identity_invalid')
    parts = manifest['version'].split('.')
    if len(parts) != 3 or any(not part.isdigit() for part in parts) or any(len(part) > 1 and part.startswith('0') for part in parts):
        raise ValueError('version_invalid')
    expected = {
        'normal': 6, 'missing_information': 4, 'tool_failure': 4,
        'conflicting_evidence': 4, 'prompt_injection': 4,
        'invalid_tool_arguments': 3, 'approval_required': 3,
    }
    counts = {name: 0 for name in expected}
    identifiers = []
    for row in cases:
        if type(row) is not dict:
            raise TypeError('case_not_dict')
        if set(row) != {'case_id','category'}:
            raise ValueError('case_shape_invalid')
        if type(row['case_id']) is not str or type(row['category']) is not str:
            raise TypeError('case_field_not_string')
        if not row['case_id'].strip() or not row['category'].strip():
            raise ValueError('case_field_blank')
        if row['category'] not in counts:
            raise ValueError('category_unknown')
        identifiers.append(row['case_id'])
        counts[row['category']] += 1
    if len(identifiers) != 28 or len(set(identifiers)) != len(identifiers):
        raise ValueError('case_identity_invalid')
    if counts != expected:
        raise ValueError('category_coverage_invalid')
    return tuple(identifiers)

