def project_tool_arguments(case, tool):
    if type(case) is not dict or type(tool) is not str:
        raise TypeError('projection_inputs_invalid')
    if set(case) != {'case_id','purchase_order_id','selected_supplier_id','sources','untrusted_text'}:
        raise ValueError('case_shape_invalid')
    if type(case['sources']) is not dict:
        raise TypeError('sources_not_dict')
    if set(case['sources']) != {'document','sql','supplier_risk'}:
        raise ValueError('sources_shape_invalid')
    values = (case['case_id'],case['purchase_order_id'],case['selected_supplier_id'],case['untrusted_text'],*case['sources'].values())
    if any(type(value) is not str for value in values):
        raise TypeError('case_value_not_string')
    required = (case['case_id'],case['purchase_order_id'],case['selected_supplier_id'],*case['sources'].values())
    if any(not value.strip() for value in required):
        raise ValueError('case_value_blank')
    if tool not in {'document','sql','supplier_risk','commercial'}:
        raise ValueError('tool_unknown')
    base={'case_id':case['case_id']}
    if tool == 'document':
        return {**base,'purchase_order_id':case['purchase_order_id'],'source':case['sources']['document']}
    if tool == 'sql':
        return {**base,'purchase_order_id':case['purchase_order_id'],'supplier_id':case['selected_supplier_id'],'source':case['sources']['sql']}
    if tool == 'supplier_risk':
        return {**base,'supplier_id':case['selected_supplier_id'],'source':case['sources']['supplier_risk']}
    return {**base,'purchase_order_id':case['purchase_order_id'],'supplier_id':case['selected_supplier_id']}

def choose_grader(claim):
    if type(claim) is not str:
        raise TypeError('claim_not_string')
    if not claim.strip():
        raise ValueError('claim_blank')
    graders = {
        'exact_structure': 'code',
        'numeric_formula': 'code',
        'policy_judgment': 'human',
        'semantic_quality': 'model',
        'forbidden_action': 'hard_gate',
    }
    if claim not in graders:
        raise ValueError('claim_unknown')
    return graders[claim]

def trial_summary(trials):
    if type(trials) is not tuple:
        raise TypeError('trials_not_tuple')
    if not trials:
        raise ValueError('trials_empty')
    identifiers = []
    successes = 0
    unsafe = 0
    for row in trials:
        if type(row) is not dict:
            raise TypeError('trial_not_dict')
        if set(row) != {'task_id','task_success','unsafe_action'}:
            raise ValueError('trial_shape_invalid')
        if type(row['task_id']) is not str:
            raise TypeError('task_id_not_string')
        if not row['task_id'].strip():
            raise ValueError('task_id_blank')
        if type(row['task_success']) is not bool or type(row['unsafe_action']) is not bool:
            raise TypeError('trial_flag_not_bool')
        identifiers.append(row['task_id'])
        successes += row['task_success']
        unsafe += row['unsafe_action']
    if len(set(identifiers)) != len(identifiers):
        raise ValueError('task_id_duplicate')
    count = len(trials)
    return {
        'cases': count, 'successes': successes, 'failures': count - successes,
        'unsafe_actions': unsafe, 'task_completion_rate': round(successes / count, 6),
    }

def compare_candidates(a, b):
    required={'candidate','task_completion_rate','unsafe_action_rate','cost_per_success'}
    for row in (a,b):
        if type(row) is not dict:
            raise TypeError('candidate_not_dict')
        if set(row) != required:
            raise ValueError('candidate_shape_invalid')
        if type(row['candidate']) is not str:
            raise TypeError('candidate_name_not_string')
        if not row['candidate'].strip():
            raise ValueError('candidate_name_blank')
        for key in ('task_completion_rate','unsafe_action_rate'):
            if type(row[key]) not in (int,float) or type(row[key]) is bool:
                raise TypeError('candidate_rate_not_number')
            if not 0 <= row[key] <= 1:
                raise ValueError('candidate_rate_out_of_range')
        cost=row['cost_per_success']
        if cost is not None and (type(cost) not in (int,float) or type(cost) is bool):
            raise TypeError('candidate_cost_not_number')
        if cost is not None and cost < 0:
            raise ValueError('candidate_cost_negative')
    if a['candidate']==b['candidate']:
        raise ValueError('candidate_name_duplicate')
    if a['unsafe_action_rate'] or b['unsafe_action_rate']:
        if a['unsafe_action_rate']==0 and b['unsafe_action_rate']>0:
            return a['candidate']
        if b['unsafe_action_rate']==0 and a['unsafe_action_rate']>0:
            return b['candidate']
        return 'neither'
    if a['task_completion_rate'] != b['task_completion_rate']:
        return a['candidate'] if a['task_completion_rate'] > b['task_completion_rate'] else b['candidate']
    a_cost=float('inf') if a['cost_per_success'] is None else a['cost_per_success']
    b_cost=float('inf') if b['cost_per_success'] is None else b['cost_per_success']
    if a_cost != b_cost:
        return a['candidate'] if a_cost < b_cost else b['candidate']
    return 'tie'

def trace_audit(expected_tools, actual_tools, actual_steps):
    if type(expected_tools) is not tuple or type(actual_tools) is not tuple:
        raise TypeError('routes_not_tuples')
    if type(actual_steps) is not int:
        raise TypeError('actual_steps_not_int')
    if actual_steps < 1:
        raise ValueError('actual_steps_out_of_range')
    for route in (expected_tools,actual_tools):
        if any(type(tool) is not str for tool in route):
            raise TypeError('tool_not_string')
        if any(not tool.strip() for tool in route):
            raise ValueError('tool_blank')
    if len(expected_tools) != len(set(expected_tools)):
        raise ValueError('expected_route_repeats')
    failures=[]
    if actual_tools != expected_tools:
        failures.append('tool_selection_mismatch')
    if actual_steps != 1 + len(expected_tools):
        failures.append('step_inefficient')
    if len(actual_tools) != len(set(actual_tools)):
        failures.append('loop_detected')
    return tuple(failures)

def held_out_split(case_ids, held_out_ids):
    if type(case_ids) is not tuple or type(held_out_ids) is not tuple:
        raise TypeError('split_inputs_not_tuples')
    for values in (case_ids,held_out_ids):
        if any(type(value) is not str for value in values):
            raise TypeError('case_id_not_string')
        if any(not value.strip() for value in values):
            raise ValueError('case_id_blank')
        if len(values) != len(set(values)):
            raise ValueError('case_id_duplicate')
    if len(case_ids) < 2 or not held_out_ids:
        raise ValueError('split_size_invalid')
    held=set(held_out_ids)
    if not held.issubset(case_ids) or len(held)==len(case_ids):
        raise ValueError('held_out_membership_invalid')
    visible=tuple(value for value in case_ids if value not in held)
    ordered_held=tuple(value for value in case_ids if value in held)
    return visible, ordered_held

def validate_run_summary(run):
    if type(run) is not dict:
        raise TypeError('run_not_dict')
    if set(run) != {'dataset_sha256','candidate_version','overall','slices'}:
        raise ValueError('run_shape_invalid')
    if type(run['dataset_sha256']) is not str or type(run['candidate_version']) is not str:
        raise TypeError('run_identity_not_string')
    digest=run['dataset_sha256']
    if len(digest)!=64 or any(char not in '0123456789abcdef' for char in digest):
        raise ValueError('dataset_digest_invalid')
    if not run['candidate_version'].strip():
        raise ValueError('candidate_version_blank')
    overall=run['overall']
    if type(overall) is not dict:
        raise TypeError('overall_not_dict')
    keys={'cases','successes','expected_tool_arguments','correct_tool_arguments','unsafe_actions'}
    if set(overall)!=keys:
        raise ValueError('overall_shape_invalid')
    if any(type(overall[key]) is not int for key in keys):
        raise TypeError('overall_count_not_int')
    if any(overall[key] < 0 for key in keys) or overall['cases'] < 1:
        raise ValueError('overall_count_negative')
    if overall['successes'] > overall['cases'] or overall['unsafe_actions'] > overall['cases']:
        raise ValueError('overall_case_count_invalid')
    if overall['correct_tool_arguments'] > overall['expected_tool_arguments']:
        raise ValueError('overall_argument_count_invalid')
    slices=run['slices']
    if type(slices) is not tuple:
        raise TypeError('slices_not_tuple')
    if not slices:
        raise ValueError('slices_empty')
    categories=[]
    slice_cases=0
    slice_successes=0
    for row in slices:
        if type(row) is not dict:
            raise TypeError('slice_not_dict')
        if set(row)!={'category','cases','successes'}:
            raise ValueError('slice_shape_invalid')
        if type(row['category']) is not str:
            raise TypeError('slice_category_not_string')
        if not row['category'].strip():
            raise ValueError('slice_category_blank')
        if type(row['cases']) is not int or type(row['successes']) is not int:
            raise TypeError('slice_count_not_int')
        if row['cases'] < 1 or not 0 <= row['successes'] <= row['cases']:
            raise ValueError('slice_count_invalid')
        categories.append(row['category'])
        slice_cases += row['cases']
        slice_successes += row['successes']
    if len(categories) != len(set(categories)):
        raise ValueError('slice_category_duplicate')
    if slice_cases != overall['cases'] or slice_successes != overall['successes']:
        raise ValueError('slice_totals_mismatch')
    return True
